/* MUTANT: one refusal broken on purpose. Generated by mut/make.py. */
/* <ov-tactical> - the situation display, with a camera that banks.
 *
 * A companion to <ov-geomap>, without a map engine.
 *
 *   <ov-tactical countries lat="35.47" lon="-97.52" range="2400" pitch="30" bearing="-18" ring="800" source="picture"></ov-tactical>
 *   map.data = [{ id: 'AX-11', lat, lon, hdg, alt, spd, at }, { id: 'DELTA', kind: 'site', lat, lon, note },
 *               { id: 'JFK-LHR', label, from, to, pos }];
 *
 * Attributes: lat, lon (the centre the camera looks at), range (km from the
 * centre to the edge of the glass when looking straight down, default 2000),
 * bearing (the direction the camera faces, degrees), pitch (0 is straight down,
 * default 30, never past 45), fov (degrees, default 35), ring (km; draws the
 * range ring and the screen circle), countries (see ov-geo.js), fresh,
 * source, src, orbit (drag, arrow keys and ctrl-scroll move the camera; it
 * announces ov:view).
 *
 * ⭐ THE FINDING THIS EXISTS FOR: A RANGE RING IS NOT A CIRCLE. Under a
 * pitched camera the ring on the ground is an ellipse on the glass. The screen
 * circle a HUD draws beside it is sized to be right NORTH of the centre, and
 * the key prints where it really reaches north and east, measured by casting
 * those screen points back onto the ground. At 48 degrees that measured 851
 * and 553 km for an 800 km ring.
 *
 * The ground is azimuthal equidistant about the centre: distance and bearing
 * FROM THE CENTRE are true, so the true ring is exactly a circle on it.
 * Distances between two other points are not, and the key says so.
 *
 * Tracks and routes follow ov-geo.js: a stale track is dashed, says how old it
 * is and draws no heading; a track with no heading says NO HEADING; a route
 * with no fix is a still plan. The heading line is a real ten-minute lead at
 * the reported speed, measured on the ground, and only for a fresh fix.
 */

import { define, whenArrived, watchSeen, isSeen } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';
import {
  R, rad, dot, cross, norm, angle, toVec, valid, ll, greatCircle, onRoute, destination, judge, fixWords,
  nextDue, remember, dated, countriesFor, countriesRefusal, onCountries, setCountries, getCountries,
  decode, placeLabel, fmtKm, esc,
} from './lib/k-stale-reads-fresh.js';

const f1 = (n) => n.toFixed(1);
const PITCH_MAX = 45;
const LEAD_MIN = 10;

class OvTactical extends HTMLElement {
  static observedAttributes = ['lat', 'lon', 'range', 'bearing', 'pitch', 'fov', 'ring', 'countries', 'fresh', 'source', 'src', 'orbit'];
  static now = () => Date.now();
  static get countries() { return getCountries(); }
  static set countries(d) { setCountries(d); }

  constructor() {
    super();
    this._tracks = { last: new Map(), prev: new Map() };
    this._trips = { last: new Map(), prev: new Map() };
    this._labels = { slots: new Map(), boxes: [], x0: 0 };
  }

  connectedCallback() {
    this._ro = new ResizeObserver(() => this.paint());
    this._ro.observe(this);
    this._unseen = watchSeen(this, () => this.paint());
    this._uncountries = onCountries(() => this.paint());
    this.addEventListener('pointerdown', this.onDrag);
    this.addEventListener('wheel', this.onWheel, { passive: false });
    this.addEventListener('keydown', this.onKey);
    this.bindSource();
    this.load();
    this.paint();
  }

  disconnectedCallback() {
    this._ro?.disconnect();
    this._ro = null;
    this._unseen?.();
    this._uncountries?.();
    this.removeEventListener('pointerdown', this.onDrag);
    this.removeEventListener('wheel', this.onWheel);
    this.removeEventListener('keydown', this.onKey);
    if (this.unsub) this.unsub();
    this.unsub = null;
    clearTimeout(this._timer);
    this._unarrive?.();
    this._unarrive = null;
  }

  attributeChangedCallback(name) {
    if (!this._ro) return;
    if (name === 'source') this.bindSource();
    if (name === 'src') this.load();
    this.paint();
  }

  // Each attribute is read by its literal name: tools/api.py documents what an
  // element reads, and a name passed through a helper reads as never read.
  num(raw, fallback) {
    const v = Number(raw);
    return raw !== null && String(raw).trim() !== '' && Number.isFinite(v) ? v : fallback;
  }
  get lat() { return Math.max(-89.9, Math.min(89.9, this.num(this.getAttribute('lat'), 0))); }
  get lon() { return this.num(this.getAttribute('lon'), 0); }
  get range() { return Math.max(20, this.num(this.getAttribute('range'), 2000)); }
  get bearing() { return this.num(this.getAttribute('bearing'), 0); }
  get pitch() { return Math.max(0, Math.min(PITCH_MAX, this.num(this.getAttribute('pitch'), 30))); }
  get fov() { return Math.max(10, Math.min(90, this.num(this.getAttribute('fov'), 35))); }
  get ring() { const r = this.num(this.getAttribute('ring'), 0); return r > 0 ? r : 0; }
  get fresh() { const v = this.num(this.getAttribute('fresh'), 60); return v > 0 ? v : 60; }

  /* Rows with `from` or `to` are routes; the rest are tracks and sites. */
  get data() { return this._rows; }
  set data(rows) {
    const list = Array.isArray(rows) ? rows : [...(rows?.tracks || []), ...(rows?.routes || [])];
    this._rows = list.filter((r) => r && typeof r === 'object');
    this._routes = this._rows.filter((r) => 'from' in r || 'to' in r);
    this._marks = this._rows.filter((r) => !('from' in r || 'to' in r));
    remember(this._tracks, this._marks.filter((m) => m.kind !== 'site'), null);
    remember(this._trips, this._routes);
    this._heard = true;
    this.paint();
  }

  get countriesData() { return this._countries; }
  set countriesData(d) { this._countries = d; this._plane = null; this.paint(); }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    this._heard = false;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (rows) => { this.data = rows; });
  }

  async load() {
    const src = this.getAttribute('src');
    this._srcFail = null;
    if (!src) return;
    let data;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch { data = undefined; }
    if (this.getAttribute('src') !== src) return;
    if (data === undefined) { this._srcFail = src; this.paint(); return; }
    const now = OvTactical.now();
    const list = Array.isArray(data) ? data : [...(data?.tracks || []), ...(data?.routes || [])];
    this.data = list.map((r) => (!r || typeof r !== 'object' ? r
      : 'from' in r || 'to' in r ? { ...r, pos: dated(r.pos, now) } : dated(r, now)));
  }

  // ── the camera, moved by hand only with `orbit` ────────────────────────
  moved() {
    this.dispatchEvent(new CustomEvent('ov:view', {
      bubbles: true,
      detail: { lat: this.lat, lon: this.lon, range: this.range, bearing: this.bearing, pitch: this.pitch },
    }));
  }
  onDrag = (e) => {
    if (!this.hasAttribute('orbit') || e.button !== 0) return;
    const x0 = e.clientX, y0 = e.clientY, b0 = this.bearing, p0 = this.pitch;
    this.setPointerCapture?.(e.pointerId);
    const move = (m) => {
      this.setAttribute('bearing', f1(b0 - (m.clientX - x0) * 0.3));
      this.setAttribute('pitch', f1(Math.max(0, Math.min(PITCH_MAX, p0 + (m.clientY - y0) * 0.25))));
    };
    const up = () => {
      this.removeEventListener('pointermove', move);
      this.removeEventListener('pointerup', up);
      this.removeEventListener('pointercancel', up);
      this.moved();
    };
    this.addEventListener('pointermove', move);
    this.addEventListener('pointerup', up);
    this.addEventListener('pointercancel', up);
  };
  // Zoom only with ctrl or cmd held (a trackpad pinch sends ctrl): a map that
  // takes the plain wheel traps a page's scroll the moment it passes under it.
  onWheel = (e) => {
    if (!this.hasAttribute('orbit') || !(e.ctrlKey || e.metaKey)) return;
    e.preventDefault();
    this.setAttribute('range', Math.round(this.range * Math.exp(e.deltaY * 0.004)));
    this.moved();
  };
  onKey = (e) => {
    if (!this.hasAttribute('orbit')) return;
    const step = { ArrowLeft: ['bearing', -5], ArrowRight: ['bearing', 5], ArrowUp: ['pitch', 5], ArrowDown: ['pitch', -5] }[e.key];
    if (!step) return;
    e.preventDefault();
    const [name, by] = step;
    const next = name === 'pitch' ? Math.max(0, Math.min(PITCH_MAX, this.pitch + by)) : this.bearing + by;
    this.setAttribute(name, f1(next));
    this.moved();
  };

  // ── the ground: azimuthal equidistant about the centre ──────────────────
  plane(c) {
    const data = c.state === 'ready' ? c.data : null;
    const key = `${this.lat},${this.lon}`;
    if (this._plane && this._plane.key === key && this._plane.data === data) return this._plane;
    const cv = toVec(this.lat, this.lon);
    const east = norm(cross([0, 0, 1], cv));
    const north = cross(cv, east);
    const at = (lat, lon) => {
      const v = toVec(lat, lon), a = angle(cv, v);
      if (a > 2.6) return null;              // toward the antipode the plane smears: refuse the point
      const az = Math.atan2(dot(v, east), dot(v, north));
      return [a * R * Math.sin(az), a * R * Math.cos(az)];
    };
    const grat = [];
    for (let lon = -180; lon < 180; lon += 10) grat.push(Array.from({ length: 161 }, (_, i) => at(-80 + i, lon)));
    for (let lat = -80; lat <= 80; lat += 10) grat.push(Array.from({ length: 361 }, (_, i) => at(lat, -180 + i)));
    let arcs = [], rings = [];
    if (data) {
      const d = decode(data);
      arcs = d.arcs.map((pts) => pts.map(([lo, la], i) => ({
        p: at(la, lo),
        // the ±180 cut in the data is not a border
        seam: i > 0 && Math.abs(lo) > 179.9 && Math.abs(pts[i - 1][0]) > 179.9,
      })));
      for (const ring of d.rings) {
        const pts = ring.map(([lo, la]) => at(la, lo));
        if (pts.every(Boolean)) rings.push(pts);
      }
    }
    this._plane = { key, data, at, grat, arcs, rings };
    return this._plane;
  }

  camera(W, H) {
    const b = rad(this.bearing), p = rad(this.pitch);
    const D = this.range / Math.tan(rad(this.fov) / 2);
    const F = (W / 2) * D / this.range;
    const cb = Math.cos(b), sb = Math.sin(b), cp = Math.cos(p), sp = Math.sin(p);
    const near = D * 0.04;
    const view = ([x, y]) => [x * cb - y * sb, x * sb + y * cb];
    const depth = (yv) => D + yv * sp;
    const screen = ([xv, yv]) => { const z = depth(yv); return [W / 2 + (xv * F) / z, H / 2 - (yv * cp * F) / z]; };
    const project = (pt) => { if (!pt) return null; const v = view(pt); return depth(v[1]) < near ? null : screen(v); };
    // A screen point back onto the ground; null if its ray never meets it.
    const unproject = (sx, sy) => {
      const k = -(sy - H / 2) / F, den = cp - k * sp;
      if (den <= 1e-6) return null;
      const yv = (k * D) / den, xv = ((sx - W / 2) / F) * depth(yv);
      return [xv * cb + yv * sb, -xv * sb + yv * cb];
    };
    // A ground polygon clipped to the near plane (one Sutherland-Hodgman pass).
    const clip = (ring) => {
      const vs = ring.map(view), out = [];
      for (let i = 0; i < vs.length; i++) {
        const a = vs[i], c = vs[(i + 1) % vs.length];
        const ia = depth(a[1]) >= near, ic = depth(c[1]) >= near;
        if (ia) out.push(a);
        if (ia !== ic) {
          const t = (near - depth(a[1])) / (depth(c[1]) - depth(a[1]));
          out.push([a[0] + t * (c[0] - a[0]), a[1] + t * (c[1] - a[1])]);
        }
      }
      return out.map(screen);
    };
    return { project, unproject, clip };
  }

  line(pts, cam) {
    let d = '', pen = false;
    for (const pt of pts) {
      const s = pt && cam.project(pt);
      if (!s) { pen = false; continue; }
      d += `${pen ? 'L' : 'M'}${f1(s[0])} ${f1(s[1])}`;
      pen = true;
    }
    return d;
  }

  label(ctx, key, s, title, sub, cls) {
    // Widths in characters of the 10 px line: the title is letter-spaced wider
    // than a character, and the 9 px second line is nearly as wide as one
    // (0.88 of a character undercounted it, and labels ran into each other).
    const spot = placeLabel(ctx.labels, key, s[0], s[1], Math.max(title.length * 1.2, sub.length), 1, ctx.W);
    return `<text class="ov-tactical__label ${cls}" x="${f1(spot.x)}" y="${f1(spot.y)}"${spot.left ? ' text-anchor="end"' : ''}>`
      + `<tspan>${title}</tspan><tspan class="ov-tactical__sub" x="${f1(spot.x)}" dy="11">${sub}</tspan></text>`;
  }

  paint() {
    if (!this.isConnected || !isSeen(this)) return;
    const now = OvTactical.now();
    const W = Math.round(this.clientWidth) || 640, H = Math.round(W * 0.62);
    const c = countriesFor(this, this.hasAttribute('countries'), this.getAttribute('countries'));
    const plane = this.plane(c);
    const cam = this.camera(W, H);
    const fresh = this.fresh;
    this._labels.boxes = [];
    this._labels.x0 = 0;
    this._labels.y0 = 0;
    this._labels.height = H;
    const ctx = { W, labels: this._labels };
    const fixes = [];
    const states = {};
    const count = (s) => { states[s] = (states[s] || 0) + 1; };

    if (this.hasAttribute('orbit')) { if (this.tabIndex < 0) this.tabIndex = 0; } else if (this.tabIndex === 0) this.removeAttribute('tabindex');

    const grat = plane.grat.map((l) => this.line(l, cam)).join('');
    let land = '', borders = '';
    for (const ring of plane.rings) {
      const s = cam.clip(ring);
      if (s.length > 2) land += 'M' + s.map(([x, y]) => `${f1(x)} ${f1(y)}`).join('L') + 'Z';
    }
    for (const arc of plane.arcs) {
      let pen = false;
      for (const q of arc) {
        const s = cam.project(q.p);
        if (!s) { pen = false; continue; }
        borders += `${pen && !q.seam ? 'L' : 'M'}${f1(s[0])} ${f1(s[1])}`;
        pen = true;
      }
    }

    // The ring on the ground, and the screen circle sized to be right north.
    let ringSvg = '', ringWords = '';
    const ring = this.ring;
    if (ring) {
      ringSvg += `<path class="ov-tactical__true" d="${this.line(Array.from({ length: 181 }, (_, i) => [ring * Math.sin(rad(i * 2)), ring * Math.cos(rad(i * 2))]), cam)}"/>`;
      const c0 = cam.project([0, 0]), n0 = cam.project([0, ring]);
      if (c0 && n0) {
        const r = Math.hypot(n0[0] - c0[0], n0[1] - c0[1]);
        ringSvg += `<circle class="ov-tactical__naive" cx="${f1(c0[0])}" cy="${f1(c0[1])}" r="${f1(r)}"/>`;
        const up = cam.unproject(c0[0], c0[1] - r), right = cam.unproject(c0[0] + r, c0[1]);
        const nKm = up && Math.hypot(...up), eKm = right && Math.hypot(...right);
        const worst = Math.max(nKm === null ? Infinity : Math.abs(nKm - ring), eKm === null ? Infinity : Math.abs(eKm - ring));
        ringWords = `<span class="ov-tactical__circle"><i class="is-naive"></i>screen circle reaches N ${nKm === null ? 'PAST THE HORIZON' : fmtKm(nKm)}, `
          + `E ${eKm === null ? 'PAST THE HORIZON' : fmtKm(eKm)}${Number.isFinite(worst) ? `, off by up to ${fmtKm(worst)} (${((worst / ring) * 100).toFixed(1)}%)` : ''}</span>`;
        this._circle = { n: nKm, e: eKm };
      }
    }

    // Routes.
    let routes = '', labels = '';
    let unplaced = 0;
    for (const r of this._routes || []) {
      if (!valid(r.from) || !valid(r.to)) { unplaced += 1; continue; }
      const from = ll(r.from), to = ll(r.to), gc = greatCircle(from, to);
      const id = r.id ?? r.label ?? `${from.lat},${from.lon}`;
      const state = judge(r.pos, this._trips.prev.get(id), now, fresh);
      const words = [];
      let cut = 0, head = '', at = from;
      if (state !== 'plan') {
        at = ll(r.pos);
        const o = onRoute(gc, at);
        cut = Math.round(o.frac * gc.n);
        if (o.xtKm > 25) words.push(`${fmtKm(o.xtKm)} OFF ROUTE`);
        fixes.push(r.pos);
        const s = cam.project(plane.at(at.lat, at.lon));
        if (s) head = `<g class="ov-tactical__head" transform="translate(${f1(s[0])} ${f1(s[1])})"><circle r="4"/>`
          + `${state === 'live' ? '<circle class="ov-tactical__ping" r="4"/>' : ''}</g>`;
      }
      words.push(fixWords(state, r.pos, now));
      const pts = gc.points.map((q) => plane.at(q.lat, q.lon));
      let g = `<path class="ov-tactical__route is-ahead" d="${this.line(pts.slice(cut), cam)}"/>`;
      if (cut) g += `<path class="ov-tactical__route is-flown" d="${this.line(pts.slice(0, cut + 1), cam)}"/>`;
      for (const e of [from, to]) {
        const s = cam.project(plane.at(e.lat, e.lon));
        if (s) g += `<rect class="ov-tactical__end" x="${f1(s[0] - 3)}" y="${f1(s[1] - 3)}" width="6" height="6"/>`;
      }
      routes += `<g class="ov-tactical__trip" data-ov-state="${state}" data-ov-id="${esc(id)}">${g}${head}</g>`;
      const s = cam.project(plane.at(at.lat, at.lon));
      if (s) labels += this.label(ctx, `r:${id}`, s, `${esc(r.label ?? '')} ${fmtKm(gc.km)}`.trim(), esc(words.join(' · ')), `is-${state}`);
      count(state);
    }

    // Tracks and sites.
    let marks = '';
    let off = 0, nofix = 0;
    for (const t of this._marks || []) {
      if (!valid(t)) { nofix += 1; continue; }
      const id = t.id ?? t.label ?? `${t.lat},${t.lon}`;
      const site = t.kind === 'site';
      const p = ll(t);
      const s = cam.project(plane.at(p.lat, p.lon));
      if (!s || s[0] < 0 || s[0] > W || s[1] < 0 || s[1] > H) { off += 1; continue; }
      const state = site ? 'site' : judge(t, this._tracks.prev.get(id), now, fresh);
      if (!site) fixes.push(t);
      const fine = state === 'live' || state === 'held';
      const hdg = t.hdg === null || t.hdg === undefined || t.hdg === '' ? NaN : Number(t.hdg);
      const spd = t.spd === null || t.spd === undefined || t.spd === '' ? NaN : Number(t.spd);
      let lead = '';
      if (fine && Number.isFinite(hdg) && Number.isFinite(spd) && spd > 0) {
        const d = destination(p.lat, p.lon, hdg, spd * 1.852 * (LEAD_MIN / 60));
        const e = cam.project(plane.at(d.lat, d.lon));
        if (e) lead = `<path class="ov-tactical__lead" d="M${f1(s[0])} ${f1(s[1])}L${f1(e[0])} ${f1(e[1])}"/>`;
      }
      const shape = site
        ? `<circle class="ov-tactical__mark" cx="${f1(s[0])}" cy="${f1(s[1])}" r="3.5"/>`
        : `<rect class="ov-tactical__mark" x="${f1(s[0] - 3.5)}" y="${f1(s[1] - 3.5)}" width="7" height="7" transform="rotate(45 ${f1(s[0])} ${f1(s[1])})"/>`;
      marks += `<g class="ov-tactical__track" data-ov-state="${state}" data-ov-id="${esc(id)}">${lead}${shape}</g>`;
      let sub;
      if (site) sub = esc(t.note ?? '');
      else if (fine) {
        const alt = t.alt === null || t.alt === undefined || t.alt === '' ? NaN : Number(t.alt);
        sub = [Number.isFinite(hdg) ? `${Math.round(((hdg % 360) + 360) % 360)}°` : 'NO HEADING',
          Number.isFinite(alt) ? `FL${Math.round(alt / 100)}` : '', Number.isFinite(spd) ? `${Math.round(spd)} KT` : '']
          .filter(Boolean).join(' · ') + (state === 'held' ? ' · NOT MOVED' : '');
      } else sub = `${fixWords(state, t, now)}${state === 'stale' ? ', HEADING NOT SHOWN' : ''}`;
      labels += this.label(ctx, `t:${id}`, s, esc(t.label ?? t.id ?? ''), sub, `is-${state}`);
      if (!site) count(state);
    }

    const key = [];
    const refuse = (s) => key.push(`<b class="ov-tactical__refuse">${s}</b>`);
    key.push(`<span>${this.lat.toFixed(2)}, ${this.lon.toFixed(2)} · ${fmtKm(this.range)} · BRG ${Math.round(((this.bearing % 360) + 360) % 360)}° · PITCH ${Math.round(this.pitch)}°</span>`);
    if (ring) key.push(`<span><i class="is-true"></i>${fmtKm(ring)} on the ground</span>`);
    if (ringWords) key.push(ringWords);
    const nope = countriesRefusal(c);
    if (nope) refuse(esc(nope));
    if (off || nofix) refuse([off ? `${off} OFF THIS VIEW` : '', nofix ? `${nofix} WITHOUT A POSITION` : ''].filter(Boolean).join(' · '));
    if (unplaced) refuse(`${unplaced} ROUTE${unplaced > 1 ? 'S' : ''} WITHOUT BOTH ENDS`);
    if (this.getAttribute('source') && !this._heard) refuse('NO FEED: nothing received from the source');
    if (this._srcFail) refuse(`SCENE FAILED TO LOAD: ${esc(this._srcFail)}`);
    key.push('<span class="ov-tactical__rule ov-aside">ground: azimuthal equidistant about the centre, so only distances FROM the centre are true</span>');

    this.innerHTML = `<svg class="ov-tactical__svg" viewBox="0 0 ${W} ${H}" aria-hidden="true">`
      + `<path class="ov-tactical__grid" d="${grat}"/>`
      + (land ? `<path class="ov-tactical__land" d="${land}"/>` : '')
      + (borders ? `<path class="ov-tactical__border" d="${borders}"/>` : '')
      + ringSvg + routes + marks + labels
      + `</svg><span class="ov-tactical__key">${key.join('')}</span>`;

    const counts = Object.entries(states).map(([s, n]) => `${n} ${s}`).join(', ');
    this.setAttribute('role', 'img');
    this.setAttribute('aria-label', `tactical view at ${this.lat.toFixed(2)}, ${this.lon.toFixed(2)}, pitched ${Math.round(this.pitch)} degrees`
      + (counts ? `; ${counts}` : '') + (off ? `; ${off} off this view` : '') + (nofix ? `; ${nofix} without a position` : '')
      + (this._circle && ring ? `. A screen circle sized to ${ring} km north reaches ${this._circle.n === null ? 'past the horizon' : Math.round(this._circle.n) + ' km'} north and ${this._circle.e === null ? 'past the horizon' : Math.round(this._circle.e) + ' km'} east` : '')
      + (nope ? `. ${nope}` : '') + '.');
    this.schedule(nextDue(fixes, now, fresh), now);
  }

  schedule(due, now) {
    clearTimeout(this._timer);
    this._timer = null;
    this._unarrive?.();
    this._unarrive = null;
    if (due === null) return;
    // ⚠️ After arrival whenArrived() runs this at once and returns a no-op;
    // keeping that no-op would cancel nothing, so it is kept only before.
    let started = false;
    const off = whenArrived(() => {
      started = true;
      this._timer = setTimeout(() => { this._timer = null; this.paint(); }, Math.max(0, due - now) + 20);
    });
    if (!started) this._unarrive = off;
  }
}

define('ov-tactical', OvTactical);

export { OvTactical };
